// DevOps – extended bank (V1.1): tool knowledge and 2025–2026 trends
// (GitHub Actions, GitLab CI, Argo CD, Prometheus, OpenTelemetry, Vault, Kyverno,
// Crossplane, Karpenter, service mesh, live troubleshooting).
import { kp, Q } from './kp.js';

const CI = 'CI/CD Tools', GO = 'GitOps & Helm', K = 'Kubernetes', OB = 'Observability & SRE', SEC = 'DevSecOps',
  IAC = 'Infrastructure as Code', LX = 'Linux', NET = 'Networking', AWS = 'Cloud (AWS)', MESH = 'Service Mesh',
  ART = 'Artifacts & Code Quality', TS = 'Troubleshooting', DK = 'Docker', PE = 'Platform Engineering', SC = 'Scripting';

export const DEVOPS_MORE = [
  // ---------- CI/CD tools ----------
  Q('devops-101', CI, 'EM', 'concept', 'Explain the structure of a GitHub Actions workflow.',
    [kp('Workflow YAML in .github/workflows with triggers (on)', 'github workflows', 'trigger*', 'on push', 'pull request'), kp('Jobs run on runners, in parallel by default', 'job*', 'runner*', 'parallel'), kp('Steps use actions or run commands', 'step*', 'action*', 'run'), kp('needs for dependencies, matrix builds', 'needs', 'matrix'), kp('Secrets, environments, caching', 'secret*', 'environment*', 'cach*')],
    'A workflow is a YAML file in the github workflows directory. It starts with triggers under on, such as push, pull request, schedule or workflow dispatch. It contains jobs that run on runners, GitHub hosted or self hosted, in parallel by default, with needs to declare dependencies between jobs. Each job has steps that either use reusable actions, like actions checkout, or run shell commands. A matrix runs the same job across versions or platforms. Secrets and environments, with protection rules and approvals, handle deployments, and actions cache speeds up dependencies.',
    'How do reusable workflows differ from composite actions?'),
  Q('devops-102', CI, 'MS', 'concept', 'How do you secure GitHub Actions pipelines?',
    [kp('OIDC to cloud instead of stored keys', 'oidc', 'no long lived', 'federat*'), kp('Pin third-party actions to commit SHA', 'pin*', 'commit sha', 'sha'), kp('Least-privilege GITHUB_TOKEN permissions', 'permissions', 'github token', 'least privilege'), kp('Protect against pull_request_target / untrusted input injection', 'pull request target', 'untrusted', 'injection', 'fork*'), kp('Environment protection and secret scoping', 'environment protection', 'required reviewer*', 'environment secret*')],
    'I use OIDC federation to cloud providers so workflows get short lived credentials and no long lived keys are stored as secrets. Third party actions are pinned to a full commit SHA, since tags can be moved, as the tj-actions compromise showed. The GITHUB_TOKEN gets least privilege permissions declared per workflow, read only by default. I avoid running untrusted code from forks with secrets, so pull request target is used carefully, and I never interpolate untrusted input like PR titles directly into shell scripts, which enables injection. Production deploys use environment protection rules with required reviewers and environment secrets.',
    'Why is a self-hosted runner on a public repository dangerous?'),
  Q('devops-103', CI, 'MS', 'concept', 'GitHub Actions, GitLab CI, Jenkins or Azure Pipelines: how would you choose a CI/CD tool?',
    [kp('Where code lives / integration', 'github', 'gitlab', 'where the code', 'integration'), kp('Hosted vs self-managed and maintenance cost', 'self managed', 'hosted', 'maintenance', 'plugin*'), kp('Jenkins flexibility but plugin/upkeep burden', 'jenkins', 'flexib*'), kp('Security and compliance features', 'security', 'complian*', 'audit'), kp('Cost, runners, team skills', 'cost', 'runner*', 'skill*')],
    'I start from where the code lives: GitHub Actions is natural for GitHub, GitLab CI for GitLab with its integrated registry and security scanning, and Azure Pipelines for Azure DevOps shops and Microsoft heavy enterprises. Jenkins is extremely flexible and self managed, which suits unusual on-premise requirements, but carries real maintenance cost: controller upkeep, plugin upgrades and security patches. I compare hosted versus self managed runners, security and compliance features such as OIDC, audit logs and approvals, cost per minute, and team skills. For most new teams a hosted, YAML based tool next to the code wins.',
    'How would you migrate 200 Jenkins jobs to a new CI tool?'),
  Q('devops-104', CI, 'EM', 'concept', 'Explain the structure of a GitLab CI pipeline.',
    [kp('.gitlab-ci.yml in repo', 'gitlab ci yml', 'gitlab ci'), kp('Stages run sequentially, jobs in a stage in parallel', 'stage*', 'sequential*', 'parallel'), kp('Runners and executors (Docker, Kubernetes)', 'runner*', 'executor*'), kp('rules / only-except, needs for DAG', 'rules', 'needs', 'dag'), kp('Artifacts, cache, environments', 'artifact*', 'cache', 'environment*')],
    'The pipeline is defined in a gitlab ci yml file in the repository. It declares stages, such as build, test and deploy, which run sequentially, while jobs in the same stage run in parallel; needs can turn it into a DAG so jobs start as soon as their dependencies finish. Jobs run on GitLab runners with executors such as Docker or Kubernetes. rules decide when a job runs, for example only on main or for merge requests. Artifacts pass files between jobs, cache speeds up dependencies, and environments track deployments with manual approval jobs. include and extends reuse templates.',
    'What is the difference between cache and artifacts in GitLab CI?'),
  Q('devops-105', CI, 'MS', 'scenario', 'A CI pipeline takes 35 minutes and developers start bypassing it. How do you speed it up?',
    [kp('Measure: find the slowest stages', 'measure', 'slowest', 'profil*', 'timing'), kp('Caching dependencies and Docker layers', 'cach*', 'layer*'), kp('Parallelise and split tests', 'parallel*', 'split', 'shard*'), kp('Only build what changed (monorepo path filters)', 'changed', 'path*', 'affected', 'monorepo'), kp('Faster runners, fail fast ordering', 'runner*', 'fail fast', 'larger')],
    'I first measure where the time goes, stage by stage, instead of guessing. Then the usual wins: caching dependencies and Docker layers, running independent jobs in parallel and splitting the test suite into shards, ordering fast checks like lint and unit tests first to fail fast, and running slow end to end tests only on main or nightly. In a monorepo I build and test only affected services using path filters. Bigger or self hosted runners and remote build caches help too. The goal is under ten minutes for the pull request feedback loop.',
    'How would you deal with flaky tests that keep failing the pipeline?'),
  Q('devops-106', CI, 'MS', 'concept', 'What is the difference between immutable artifact promotion and rebuilding per environment?',
    [kp('Build once, promote the same artifact', 'build once', 'same artifact', 'promot*'), kp('Immutable tags / digests', 'immutable', 'digest', 'sha'), kp('Config injected per environment', 'config*', 'per environment', 'environment variable*'), kp('Rebuilding risks drift and untested binaries', 'drift', 'untested', 'different binar*', 'rebuild*')],
    'With immutable artifact promotion I build once, producing a versioned artifact such as a container image identified by its digest, and promote that exact same artifact through dev, staging and production, injecting configuration per environment through environment variables, ConfigMaps or secrets. Rebuilding per environment risks drift: dependencies or base images can change between builds, so what reaches production is an untested binary that differs from what passed tests. Immutable tags or digests also make rollback and auditing simple.',
    'Why should you avoid the latest tag in production manifests?'),

  // ---------- GitOps & Helm ----------
  Q('devops-107', GO, 'MS', 'concept', 'Compare push-based and pull-based (GitOps) deployment, including security implications.',
    [kp('Push: CI pipeline applies to cluster', 'push', 'pipeline applies', 'kubectl apply'), kp('Pull: in-cluster agent syncs from Git', 'pull', 'in cluster', 'agent', 'argo cd', 'flux'), kp('Security: cluster credentials stay inside', 'credential*', 'stay inside', 'no cluster credentials', 'outside'), kp('Drift detection and reconciliation', 'drift', 'reconcil*'), kp('Audit via Git history', 'audit*', 'git history')],
    'In a push based model, the CI pipeline holds cluster credentials and runs kubectl apply or helm upgrade, so the CI system becomes a powerful attack target and nothing corrects drift afterwards. In a pull based GitOps model, an in cluster agent such as Argo CD or Flux watches Git and syncs the desired state, so cluster credentials stay inside the cluster and CI only needs write access to a Git repo. The agent continuously reconciles and detects drift from manual changes, and Git history gives an audit trail and easy rollback.',
    'How do you handle secrets in a GitOps repository?'),
  Q('devops-108', GO, 'MS', 'concept', 'How do you manage many applications and environments in Argo CD?',
    [kp('Application CRD pointing to repo path', 'application', 'crd', 'repo'), kp('App of apps / ApplicationSet generators', 'app of apps', 'applicationset', 'generator*'), kp('Projects for RBAC and restrictions', 'appproject', 'project*', 'rbac'), kp('Sync policies: automated, prune, self-heal', 'sync polic*', 'automated', 'prune', 'self heal'), kp('Sync waves / hooks for ordering', 'sync wave*', 'hook*')],
    'Each deployable unit is an Argo CD Application, a CRD pointing to a repo path, Helm chart or Kustomize overlay and a destination cluster and namespace. To manage many, I use the app of apps pattern or, better, ApplicationSet generators that create Applications per cluster, per environment or per directory automatically. AppProjects restrict which repos, clusters and namespaces each team can use and carry RBAC. Sync policies can be automated with prune and self heal. Sync waves and hooks order resources, for example running a database migration job before the deployment.',
    'How would you promote a release from staging to production with Argo CD?'),
  Q('devops-109', GO, 'MS', 'concept', 'When does Helm make things worse than plain manifests or Kustomize?',
    [kp('Helm: templating, packaging, releases', 'helm', 'templat*', 'release*'), kp('Over-templated charts become unreadable', 'over templat*', 'unreadable', 'complex*', 'values'), kp('Kustomize: patch-based overlays, no templates', 'kustomize', 'overlay*', 'patch*'), kp('Use helm template / diff to review', 'helm template', 'helm diff', 'render*'), kp('Good fit: third-party apps, reusable charts', 'third party', 'reusable', 'distribut*')],
    'Helm is great for packaging and distributing reusable charts and installing third party software like ingress controllers or Prometheus, with releases and rollback. It becomes worse when internal charts are over templated, with every field exposed as a value, nested conditionals and helper functions until nobody can read what will be deployed. For our own services with a few environment differences, Kustomize overlays that patch plain YAML are often clearer. Whatever I use, I render manifests with helm template or helm diff in CI so reviewers see the real output.',
    'How do you test a Helm chart?'),
  Q('devops-110', GO, 'SL', 'concept', 'How do you do progressive delivery (canary) on Kubernetes with automated rollback?',
    [kp('Argo Rollouts or Flagger', 'argo rollouts', 'flagger'), kp('Traffic splitting via ingress/service mesh', 'traffic split*', 'service mesh', 'ingress', 'weight*'), kp('Analysis on metrics (error rate, latency)', 'analysis', 'metric*', 'error rate', 'latency', 'prometheus'), kp('Automatic rollback on failure', 'automatic rollback', 'abort', 'roll back'), kp('Gradual steps', 'step*', 'percent*', 'gradual*')],
    'I use Argo Rollouts or Flagger instead of a plain Deployment. The rollout defines gradual steps, for example 5, 25, 50 and 100 percent, and traffic splitting is done by the ingress controller or a service mesh using weights. At each step an analysis queries metrics from Prometheus, such as error rate and p99 latency compared with the stable version; if they breach thresholds, the rollout aborts and traffic goes back to stable automatically, with an automatic rollback. Combined with feature flags this greatly reduces the blast radius of bad releases.',
    'How would you canary a change that includes a database migration?'),

  // ---------- Kubernetes deep ----------
  Q('devops-111', K, 'MS', 'concept', 'When do you use a StatefulSet, a DaemonSet, a Job or a CronJob?',
    [kp('StatefulSet: stable identity and storage for stateful apps', 'statefulset', 'stable', 'identity', 'persistent'), kp('DaemonSet: one pod per node (agents)', 'daemonset', 'every node', 'per node', 'agent*'), kp('Job: run to completion', 'job', 'completion'), kp('CronJob: scheduled jobs', 'cronjob', 'schedul*'), kp('Examples', 'database', 'log', 'backup', 'migration')],
    'A StatefulSet is for stateful apps like databases or Kafka: each pod gets a stable identity and hostname, ordered startup, and its own persistent volume claim that follows it. A DaemonSet runs one pod per node, or per selected node, for node agents such as log collectors, monitoring exporters or CNI plugins. A Job runs pods to completion, with retries, for one-off tasks like a database migration. A CronJob creates Jobs on a schedule, for example a nightly backup, with settings for concurrency and history.',
    'What happens to a StatefulSet volume when you scale down?'),
  Q('devops-112', K, 'MS', 'concept', 'How does storage work in Kubernetes? Explain PV, PVC and StorageClass.',
    [kp('PersistentVolume is the storage resource', 'persistentvolume', 'pv'), kp('PersistentVolumeClaim is the request', 'persistentvolumeclaim', 'pvc', 'claim'), kp('StorageClass enables dynamic provisioning via CSI', 'storageclass', 'dynamic provisioning', 'csi'), kp('Access modes and reclaim policy', 'access mode*', 'readwriteonce', 'reclaim polic*'), kp('Volume binding / zones', 'waitforfirstconsumer', 'zone*', 'binding')],
    'A PersistentVolume, PV, represents a piece of storage in the cluster, such as a cloud disk. A PersistentVolumeClaim, PVC, is a pod request for storage of a size and access mode. A StorageClass enables dynamic provisioning: when a PVC references it, the CSI driver creates a matching volume automatically. Access modes include ReadWriteOnce for a single node and ReadWriteMany for shared file storage. The reclaim policy decides whether the disk is deleted or retained when the claim is removed. WaitForFirstConsumer binding creates the disk in the same zone as the scheduled pod.',
    'Why might a pod be stuck Pending with an unbound PVC?'),
  Q('devops-113', K, 'MS', 'concept', 'How does Kubernetes scheduling work? Explain node selectors, affinity, taints and tolerations.',
    [kp('Scheduler filters and scores nodes', 'filter*', 'scor*', 'scheduler'), kp('nodeSelector and node affinity', 'nodeselector', 'node affinity'), kp('Pod affinity / anti-affinity, topology spread', 'anti affinity', 'pod affinity', 'topology spread'), kp('Taints repel, tolerations allow', 'taint*', 'toleration*'), kp('Resource requests drive placement', 'request*', 'resources')],
    'The scheduler first filters nodes that can run the pod, based on resource requests, ports, volumes and constraints, then scores the remaining ones and picks the best. nodeSelector and node affinity attract pods to nodes with certain labels, such as GPU nodes. Pod anti affinity and topology spread constraints spread replicas across nodes and zones for availability, while pod affinity co-locates pods. Taints on nodes repel pods unless the pods have matching tolerations, which is how you dedicate nodes to specific workloads, like the system node pool.',
    'Why should dedicated GPU nodes use both taints and node affinity?'),
  Q('devops-114', K, 'SL', 'concept', 'What are Kubernetes operators and CRDs?',
    [kp('CRD extends the Kubernetes API', 'crd', 'custom resource*', 'extend*'), kp('Operator = controller with domain knowledge', 'operator*', 'controller', 'domain knowledge'), kp('Reconciliation loop', 'reconcil*', 'desired state'), kp('Examples: Prometheus operator, cert-manager, databases', 'prometheus operator', 'cert manager', 'postgres', 'strimzi'), kp('Built with Operator SDK / kubebuilder', 'operator sdk', 'kubebuilder')],
    'A custom resource definition, CRD, extends the Kubernetes API with new resource types, such as a PostgresCluster or Certificate. An operator is a controller that watches those custom resources and runs a reconciliation loop to drive actual state towards desired state, encoding operational domain knowledge such as how to provision, back up, fail over and upgrade a database. Examples are the Prometheus operator, cert manager, Strimzi for Kafka and CloudNativePG. Operators are built with frameworks like Operator SDK or kubebuilder.',
    'What risks come with installing many third-party operators?'),
  Q('devops-115', K, 'MS', 'scenario', 'Pods pass health checks, but about 3 percent of requests return 503 errors. How do you diagnose it?',
    [kp('Correlate with deployments/scaling events', 'deploy*', 'rollout', 'scal*', 'correlat*'), kp('Termination race: endpoints vs SIGTERM, preStop', 'prestop', 'sigterm', 'graceful*', 'endpoint*'), kp('Readiness probe not reflecting real readiness', 'readiness'), kp('Ingress/LB timeouts and keep-alive mismatch', 'keep alive', 'timeout*', 'ingress', 'load balancer'), kp('Check ingress logs, upstream errors', 'ingress log*', 'upstream', 'logs')],
    'First I check whether the 503s correlate with deploys, scaling events or node drains, using ingress logs that show the upstream pod and error. A frequent cause is the termination race: when a pod gets SIGTERM it is removed from endpoints asynchronously, so the ingress still sends requests to a pod that is shutting down; a preStop sleep and graceful shutdown fix it. Others are readiness probes that pass before the app is truly ready, keep alive timeout mismatches between the load balancer and the app, too few replicas, or a pod being OOMKilled. The fix depends on which pattern the logs show.',
    'How would you verify your fix in a test before production?'),
  Q('devops-116', K, 'SL', 'concept', 'What happens when etcd is overloaded or loses quorum, and how do you protect it?',
    [kp('etcd stores all cluster state, Raft quorum', 'etcd', 'quorum', 'raft'), kp('Loss of quorum: API becomes read-only/unavailable', 'unavailable', 'read only', 'writes fail', 'cannot write'), kp('Running workloads keep running', 'keep running', 'existing pods', 'still run'), kp('Protect: odd members, fast disks, defragment, limit objects', 'odd number', 'three', 'five', 'ssd', 'defrag*', 'disk latency'), kp('Backups / snapshots', 'snapshot*', 'backup*')],
    'etcd stores all cluster state and uses Raft, so it needs a quorum, a majority of members. If it is overloaded, API server requests slow down or time out; if it loses quorum, writes fail and the API becomes unavailable, so nothing can be scheduled or changed, although existing pods keep running on nodes. To protect it I run an odd number of members, three or five, on fast SSD disks with low disk latency, monitor fsync latency and database size, defragment and compact, limit huge numbers of objects such as events and secrets, and take regular snapshots for backup. Managed Kubernetes handles most of this.',
    'Why is a two-member etcd cluster worse than a one-member one?'),
  Q('devops-117', K, 'SL', 'concept', 'How does Karpenter differ from the Cluster Autoscaler?',
    [kp('Cluster Autoscaler scales predefined node groups', 'cluster autoscaler', 'node group*', 'asg'), kp('Karpenter provisions right-sized nodes directly', 'karpenter', 'right siz*', 'directly'), kp('Flexible instance types and spot', 'instance type*', 'spot'), kp('Consolidation to reduce cost', 'consolidat*', 'bin pack*'), kp('Faster scaling', 'faster', 'seconds')],
    'The Cluster Autoscaler works with predefined node groups, such as auto scaling groups: it increases a group size when pods are pending and removes underused nodes, but every group has fixed instance types. Karpenter looks at the pending pods requirements and provisions right sized nodes directly through the cloud API, choosing from many instance types including spot, which is faster and avoids managing many node groups. It also does consolidation, repacking pods onto fewer or cheaper nodes. It started on AWS and now has providers for Azure as well.',
    'What disruption controls would you configure for Karpenter?'),
  Q('devops-118', K, 'MS', 'concept', 'How do PodDisruptionBudgets affect node maintenance and upgrades?',
    [kp('PDB limits voluntary disruptions', 'poddisruptionbudget', 'pdb', 'voluntary'), kp('minAvailable / maxUnavailable', 'minavailable', 'maxunavailable'), kp('Node drain respects PDB (eviction API)', 'drain', 'evict*'), kp('Misconfigured PDB blocks upgrades', 'block*', 'stuck', 'zero'), kp('Not for involuntary failures', 'involuntary', 'node failure', 'crash')],
    'A PodDisruptionBudget limits voluntary disruptions, such as node drains during upgrades or autoscaler scale-down, by specifying minAvailable or maxUnavailable for a set of pods. kubectl drain uses the eviction API, which refuses to evict a pod if that would violate the PDB, so the drain waits. That protects availability, but a misconfigured PDB, for example minAvailable equal to replicas or a single replica deployment with maxUnavailable zero, blocks drains and leaves upgrades stuck. PDBs do not protect against involuntary disruptions like node failure or a crash.',
    'How would you find PDBs that will block the next cluster upgrade?'),
  Q('devops-119', K, 'MS', 'concept', 'How do you manage multiple environments and clusters with kubectl and Kustomize safely?',
    [kp('kubeconfig contexts', 'kubeconfig', 'context*'), kp('Namespaces per team/environment', 'namespace*'), kp('Kustomize base and overlays', 'kustomize', 'base', 'overlay*'), kp('Avoid manual changes in prod: GitOps / read-only access', 'gitops', 'read only', 'manual'), kp('Tools: kubectx, prompt showing context', 'kubectx', 'prompt')],
    'kubectl uses kubeconfig contexts to switch clusters and namespaces, and the biggest risk is running a command against production by mistake, so I use kubectx and kubens and a shell prompt that shows the current context in red for prod. Manifests use Kustomize with a base and overlays per environment for replica counts, resources and config. Namespaces separate teams and environments within a cluster. In production, humans get read only access by default and changes flow through GitOps instead of manual kubectl apply.',
    'What would you do if someone ran kubectl delete in the wrong cluster?'),

  // ---------- Docker ----------
  Q('devops-120', DK, 'MS', 'concept', 'How do you build multi-architecture images and speed up Docker builds with BuildKit?',
    [kp('BuildKit features: cache mounts, parallel stages', 'buildkit', 'cache mount*', 'parallel'), kp('docker buildx for multi-platform (amd64/arm64)', 'buildx', 'multi platform', 'arm64', 'amd64'), kp('Remote/registry cache', 'registry cache', 'remote cache', 'cache from'), kp('Manifest list', 'manifest list', 'manifest')],
    'BuildKit is the modern Docker builder: it runs independent stages in parallel, skips unused stages, supports cache mounts so package manager caches survive between builds, and secret mounts so credentials never land in layers. docker buildx uses BuildKit to build multi platform images, for example amd64 and arm64 for Graviton or Apple silicon, either by emulation or native builders, and pushes a manifest list so each platform pulls the right image. In CI I use a registry cache with cache from and cache to, since runners are ephemeral.',
    'Why might an arm64 image built through QEMU emulation be very slow, and what is the alternative?'),
  Q('devops-121', DK, 'EM', 'concept', 'What does Docker Compose do, and when would you use it?',
    [kp('Define multi-container apps in a YAML file', 'compose', 'yaml', 'multi container'), kp('Services, networks, volumes', 'service*', 'network*', 'volume*'), kp('Local development and integration tests', 'local development', 'integration test*', 'local'), kp('Not a production orchestrator', 'not for production', 'production', 'kubernetes'), kp('depends_on and healthchecks', 'depends on', 'healthcheck*')],
    'Docker Compose defines a multi container application in a single compose YAML file: services with their images or build context, ports, environment, networks and volumes, and it starts everything with one command. Services reach each other by name through the default network. depends on with healthchecks controls startup order. I use it for local development, for example an app plus Postgres, Kafka and Redis, and for integration tests in CI. It is not a production orchestrator for multi host workloads; that is what Kubernetes or a managed container service is for.',
    'How would you make Compose wait until the database is actually ready?'),

  // ---------- Observability tools ----------
  Q('devops-122', OB, 'EM', 'concept', 'How does Prometheus work? Explain its data model and pull-based scraping.',
    [kp('Pull model: scrapes /metrics endpoints', 'pull', 'scrape*', 'metrics endpoint'), kp('Time series with labels', 'time series', 'label*'), kp('Metric types: counter, gauge, histogram, summary', 'counter', 'gauge', 'histogram', 'summary'), kp('PromQL queries', 'promql', 'rate'), kp('Service discovery, exporters, Alertmanager', 'service discovery', 'exporter*', 'alertmanager')],
    'Prometheus pulls metrics: it discovers targets through service discovery, for example Kubernetes, and scrapes their metrics endpoint at an interval. Data is stored as time series identified by a metric name and labels, such as http requests total with method and status labels. Metric types are counter, which only increases, gauge, which goes up and down, histogram and summary for distributions like latency. You query with PromQL, for example rate over a counter, and exporters such as node exporter expose metrics for systems. Alert rules send alerts to Alertmanager, which deduplicates and routes them.',
    'Why is putting a user id in a label a bad idea?'),
  Q('devops-123', OB, 'MS', 'concept', 'How do you scale Prometheus for many clusters and long-term retention?',
    [kp('Single Prometheus limits: memory, retention, HA', 'single', 'memory', 'retention', 'high availability'), kp('Thanos / Cortex / Mimir / VictoriaMetrics', 'thanos', 'cortex', 'mimir', 'victoriametrics'), kp('Remote write to long-term storage (object storage)', 'remote write', 'object storage', 's3'), kp('Cardinality control', 'cardinality'), kp('Global query view and federation', 'global view', 'federation', 'query')],
    'A single Prometheus is limited by memory, local retention and has no built in high availability or global view. For many clusters I run Prometheus or a lightweight agent in each cluster and use remote write to a scalable backend such as Grafana Mimir, Thanos, Cortex or VictoriaMetrics, which store data in object storage like S3 for long retention and provide a global query view with deduplication of HA pairs. The biggest operational issue is cardinality, so I control labels, drop unused metrics and set per tenant limits.',
    'How would you find which metrics cause a cardinality explosion?'),
  Q('devops-124', OB, 'MS', 'concept', 'What is OpenTelemetry, and how would you roll it out?',
    [kp('Vendor-neutral standard for traces, metrics, logs', 'vendor neutral', 'standard', 'traces', 'metrics', 'logs'), kp('SDKs and auto-instrumentation', 'sdk*', 'auto instrumentation', 'agent'), kp('OTel Collector: receive, process, export', 'collector', 'pipeline', 'export*'), kp('Context propagation (W3C traceparent)', 'context propagation', 'traceparent', 'w3c'), kp('Sampling', 'sampl*')],
    'OpenTelemetry is a vendor neutral CNCF standard and toolkit for traces, metrics and logs. Services are instrumented with SDKs or auto instrumentation agents, such as the Java agent, which propagate context using the W3C traceparent header so traces connect across services. Telemetry goes to the OpenTelemetry Collector, which receives, processes, for example adding Kubernetes metadata, filtering and sampling, and exports to backends like Tempo, Jaeger, Prometheus, Datadog or Application Insights. Because the backend is configured in the collector, you can switch vendors without changing code. I roll it out with auto instrumentation first and tail based sampling in the collector.',
    'Why would you choose tail-based sampling over head-based sampling?'),
  Q('devops-125', OB, 'MS', 'concept', 'Compare Loki with the ELK stack for log management.',
    [kp('ELK indexes full text (Elasticsearch)', 'elk', 'elasticsearch', 'full text', 'index*'), kp('Loki indexes only labels, stores chunks in object storage', 'loki', 'labels', 'object storage', 'chunk*'), kp('Cost and operations trade-off', 'cost', 'cheaper', 'operat*'), kp('Query: LogQL vs Kibana/KQL', 'logql', 'kibana'), kp('Shippers: Fluent Bit, Promtail/Alloy, Logstash', 'fluent bit', 'promtail', 'alloy', 'logstash', 'filebeat')],
    'The ELK stack, Elasticsearch, Logstash and Kibana, indexes the full text of every log line, which makes arbitrary searches and analytics fast but requires lots of storage, memory and operational effort. Loki indexes only labels such as namespace, app and level, and stores compressed chunks in object storage, so it is much cheaper and simpler to run, but queries filter by labels and then grep through chunks, using LogQL in Grafana. Logs are shipped with Fluent Bit, Promtail or Grafana Alloy for Loki, or Filebeat and Logstash for ELK. I pick Loki for cost-effective operational logs in Kubernetes and Elasticsearch when heavy search or analytics is needed.',
    'How do you keep logs useful and affordable at the same time?'),
  Q('devops-126', OB, 'SL', 'design', 'Design an observability stack for 40 microservices on Kubernetes.',
    [kp('Metrics: Prometheus + Grafana (or managed)', 'prometheus', 'grafana', 'metrics'), kp('Logs: Fluent Bit to Loki/ELK, structured logs', 'loki', 'fluent bit', 'structured', 'logs'), kp('Traces: OpenTelemetry to Tempo/Jaeger', 'opentelemetry', 'tempo', 'jaeger', 'trac*'), kp('Correlation by trace id', 'trace id', 'correlat*'), kp('SLO-based alerting and dashboards', 'slo', 'alert*', 'dashboard*', 'golden signal*')],
    'For metrics I would run Prometheus via kube prometheus stack, or a managed equivalent, scraping services and Kubernetes, with Grafana dashboards per service showing the golden signals. Logs are structured JSON, collected by Fluent Bit as a DaemonSet and sent to Loki, or Elasticsearch if heavy search is needed. Traces use OpenTelemetry SDKs and the collector, exporting to Tempo or Jaeger. Everything carries a trace id, so in Grafana you can jump from a metric spike to traces to the related logs, which is the correlation that matters during incidents. Alerting is SLO based through Alertmanager to PagerDuty, with runbooks, and a platform team owns it as a shared service.',
    'How would you budget storage and retention for this stack?'),
  Q('devops-127', OB, 'MS', 'concept', 'How do you write good alerts and avoid alert fatigue?',
    [kp('Alert on symptoms / user impact, not causes', 'symptom*', 'user impact', 'cause*'), kp('Actionable with runbooks', 'actionable', 'runbook*'), kp('Severity and routing: page vs ticket', 'severity', 'page', 'ticket', 'routing'), kp('Use burn rates and for durations to avoid flapping', 'burn rate', 'for duration', 'flapping', 'threshold*'), kp('Review and delete noisy alerts', 'review', 'noisy', 'delete', 'tune')],
    'Every page should be actionable and linked to a runbook; if nobody needs to act, it is a ticket or a dashboard, not an alert. I alert on symptoms of user impact, like error rate and latency against the SLO, rather than causes like high CPU. Severity determines routing: page someone only for urgent user-facing problems, otherwise create a ticket. Multi window burn rate alerts and for durations avoid flapping on short spikes. Alertmanager groups and inhibits related alerts. Finally the team reviews alerts regularly and deletes or tunes noisy ones, tracking pages per on-call shift.',
    'Disk usage at 80 percent: page, ticket, or nothing?'),

  // ---------- Security tools ----------
  Q('devops-128', SEC, 'MS', 'concept', 'How does HashiCorp Vault work, and what are dynamic secrets?',
    [kp('Central secrets management with auth methods and policies', 'vault', 'auth method*', 'polic*'), kp('Dynamic secrets: short-lived, generated on demand', 'dynamic secret*', 'short lived', 'on demand'), kp('Leases and automatic revocation', 'lease*', 'revok*', 'revocation'), kp('Kubernetes auth / agent injector / CSI', 'kubernetes auth', 'agent injector', 'csi', 'sidecar'), kp('Seal/unseal and audit', 'unseal', 'seal', 'audit')],
    'Vault centralises secrets management. Clients authenticate with auth methods, such as Kubernetes service accounts, OIDC or cloud IAM, and policies decide which paths they can read. Beyond storing static secrets, Vault generates dynamic secrets on demand: for example short lived database credentials unique to each app instance, with a lease, and they are automatically revoked when the lease expires, so leaked credentials quickly become useless. In Kubernetes, the Vault agent injector sidecar or the CSI provider delivers secrets to pods. Vault starts sealed and must be unsealed, ideally with cloud KMS auto unseal, and every access is audit logged.',
    'How would you handle Vault being unavailable for applications?'),
  Q('devops-129', SEC, 'SL', 'concept', 'Compare OPA Gatekeeper and Kyverno for Kubernetes policy enforcement.',
    [kp('Both are admission controllers', 'admission controller*', 'admission', 'webhook'), kp('Gatekeeper uses Rego policies', 'gatekeeper', 'rego', 'opa'), kp('Kyverno uses Kubernetes-native YAML', 'kyverno', 'yaml', 'kubernetes native'), kp('Kyverno can mutate and generate resources', 'mutat*', 'generat*'), kp('Audit mode before enforce', 'audit', 'enforce')],
    'Both are admission controllers that validate requests to the Kubernetes API against policies, for example blocking privileged pods or requiring labels. OPA Gatekeeper uses the general purpose Rego language, which is powerful and reusable outside Kubernetes but has a learning curve. Kyverno policies are Kubernetes native YAML, easier for platform teams, and Kyverno can also mutate resources, generate resources such as default network policies in new namespaces, and verify image signatures. Both support an audit mode to report violations before switching to enforce, which is how I roll out policies safely.',
    'Which policies would you enforce first in a new cluster?'),
  Q('devops-130', SEC, 'MS', 'concept', 'What tools do you use to scan code, dependencies, images and IaC for security issues?',
    [kp('SAST: SonarQube, Semgrep, CodeQL', 'sast', 'sonarqube', 'semgrep', 'codeql'), kp('SCA / dependency: Dependabot, Snyk, OWASP Dependency-Check', 'sca', 'dependabot', 'snyk', 'dependency check'), kp('Image scanning: Trivy, Grype', 'trivy', 'grype', 'image scan*'), kp('IaC scanning: Checkov, tfsec, KICS', 'checkov', 'tfsec', 'kics', 'iac scan*'), kp('Secret scanning: Gitleaks, TruffleHog', 'gitleaks', 'trufflehog', 'secret scan*')],
    'For SAST on source code I use SonarQube, Semgrep or GitHub CodeQL. For dependencies, SCA, I use Dependabot or Renovate for updates and Snyk or OWASP Dependency Check for known vulnerabilities. Container images are scanned with Trivy or Grype in CI and continuously in the registry. Terraform, Kubernetes and Helm files get IaC scanning with Checkov, tfsec or KICS for misconfigurations like public buckets. Secret scanning with Gitleaks or TruffleHog runs as a pre-commit hook and in CI. Results feed one place with severity thresholds that fail builds, and exceptions are tracked.',
    'How do you stop scanners from overwhelming teams with low-priority findings?'),
  Q('devops-131', SEC, 'SL', 'concept', 'What are SLSA, Sigstore and SBOMs, and how do they protect the supply chain?',
    [kp('SBOM lists components (SPDX/CycloneDX)', 'sbom', 'spdx', 'cyclonedx', 'component*'), kp('Sigstore / cosign keyless signing', 'sigstore', 'cosign', 'keyless', 'sign*'), kp('SLSA levels and provenance', 'slsa', 'provenance', 'level*'), kp('Verify at admission', 'verify', 'admission', 'policy'), kp('Respond to new CVEs quickly', 'cve*', 'respond', 'vulnerab*')],
    'An SBOM, software bill of materials in SPDX or CycloneDX format, lists every component and version in an artifact, so when a new CVE appears you can find affected images in minutes. Sigstore, with cosign, signs artifacts, often keyless using OIDC identities and a transparency log, proving who built an image. SLSA is a framework of levels for build integrity, requiring signed provenance that states how and from which source an artifact was built. In the cluster, an admission policy, with Kyverno or Sigstore policy controller, verifies signatures and provenance before running images.',
    'How would you find every running image affected by a new OpenSSL vulnerability?'),

  // ---------- IaC ----------
  Q('devops-132', IAC, 'MS', 'concept', 'Terraform vs Pulumi vs Crossplane: how do they differ?',
    [kp('Terraform/OpenTofu: HCL, state, plan/apply', 'terraform', 'opentofu', 'hcl', 'state'), kp('Pulumi: general-purpose languages', 'pulumi', 'typescript', 'python', 'general purpose'), kp('Crossplane: Kubernetes control plane, CRDs, continuous reconciliation', 'crossplane', 'kubernetes', 'reconcil*', 'crd*'), kp('Choose by team skills and platform model', 'team', 'skill*', 'platform'), kp('Licensing change (BSL) and OpenTofu fork', 'bsl', 'licen*', 'fork')],
    'Terraform uses declarative HCL with a state file and plan and apply runs; after the 2023 licence change to BSL, the community fork OpenTofu stays open source and compatible. Pulumi lets you write infrastructure in general purpose languages like TypeScript, Python or Go, with loops, functions and unit tests, still with state. Crossplane turns Kubernetes into a control plane: cloud resources are CRDs, and controllers continuously reconcile them, so drift is corrected automatically and platform teams can offer composite resources through GitOps. I choose based on team skills and the platform model; Terraform remains the most common.',
    'When would continuous reconciliation be a disadvantage?'),
  Q('devops-133', IAC, 'MS', 'scenario', 'A terraform apply failed halfway through. How do you recover?',
    [kp('State reflects created resources; do not panic-delete', 'state', 'partial*', 'already created'), kp('Read the error and fix root cause', 'error', 'root cause'), kp('Re-run plan to see remaining changes', 'plan', 're run', 'rerun'), kp('Lock issues: force-unlock carefully', 'lock*', 'force unlock'), kp('Import or state rm for out-of-sync resources', 'import', 'state rm', 'state mv')],
    'Terraform records resources in the state as soon as they are created, so a partial apply usually leaves a consistent state for what was created. I read the error and fix the root cause, such as a quota limit, permission or invalid argument, then re run terraform plan to see the remaining changes and apply again. If the state lock was left behind by the crashed run, I confirm no one else is running and use force unlock carefully. If a resource was created but not recorded, I bring it in with terraform import; if state references something that no longer exists, I use state rm. I never edit the state file by hand.',
    'How do you prevent two engineers from applying at the same time?'),
  Q('devops-134', IAC, 'SL', 'concept', 'How do you test and review infrastructure code before it reaches production?',
    [kp('fmt / validate / lint (tflint)', 'fmt', 'validate', 'tflint', 'lint*'), kp('Policy as code: OPA/Sentinel/Checkov', 'policy as code', 'sentinel', 'checkov', 'opa'), kp('Plan in PR, reviewed (Atlantis/Terraform Cloud)', 'plan', 'pull request', 'atlantis', 'terraform cloud'), kp('Tests: terraform test / Terratest', 'terraform test', 'terratest'), kp('Ephemeral environments, then promote', 'ephemeral', 'promot*', 'staging')],
    'Every change goes through a pull request. CI runs terraform fmt, validate and tflint, then security and policy as code checks with Checkov, OPA or Sentinel, for example no public storage and required tags. The plan output is posted to the PR by Atlantis, Terraform Cloud or a pipeline, and reviewers approve the plan, not only the code. Modules have tests using the native terraform test framework or Terratest, which create real resources in an ephemeral test account and destroy them. Changes are applied to dev and staging first and then promoted to production.',
    'What should a reviewer look for first in a Terraform plan?'),

  // ---------- Linux & networking ----------
  Q('devops-135', LX, 'EM', 'concept', 'How does systemd manage services? How do you troubleshoot a service that will not start?',
    [kp('Unit files define services', 'unit file*', 'unit'), kp('systemctl start/enable/status', 'systemctl', 'status', 'enable'), kp('journalctl -u for logs', 'journalctl'), kp('Restart policies and dependencies', 'restart', 'after', 'wants', 'requires'), kp('Check permissions, ports, config syntax', 'permission*', 'port', 'config*')],
    'systemd manages services through unit files that describe the command to run, the user, environment, dependencies like After and Requires, and restart policies such as Restart on failure. I use systemctl start, stop and enable for boot, and systemctl status to see state and recent log lines. To troubleshoot, journalctl with u and the service name shows the full logs. Common causes are wrong permissions on files, a port already in use, a config syntax error, a missing environment file or a dependency not ready. After editing a unit file, I run systemctl daemon-reload.',
    'How would you limit the memory a service can use with systemd?'),
  Q('devops-136', LX, 'MS', 'scenario', 'A server says the disk is full, but du does not show where the space went. What is happening?',
    [kp('Deleted files still held open by a process', 'deleted', 'held open', 'open file*'), kp('Find with lsof', 'lsof'), kp('Fix by restarting or truncating the process file', 'restart*', 'truncat*'), kp('Inode exhaustion check with df -i', 'inode*', 'df i'), kp('Log rotation done wrong', 'logrotate', 'rotation', 'log rotat*')],
    'The classic cause is a deleted file that a process still holds open, typically a large log file removed with rm while the application keeps writing: the space is not freed until the file handle closes, and du cannot see it. I find it with lsof filtering for deleted files, then restart the process or truncate the file through its proc file descriptor. Prevent it with proper log rotation, using logrotate copytruncate or signalling the app to reopen logs. I also check df i, because inode exhaustion from millions of small files shows disk full with free space.',
    'How would you find the largest directories quickly on a huge filesystem?'),
  Q('devops-137', NET, 'MS', 'scenario', 'An application cannot connect to a database on another host. How do you troubleshoot network connectivity?',
    [kp('DNS resolution check (dig/nslookup)', 'dns', 'dig', 'nslookup'), kp('Port reachability (nc/telnet/curl)', 'nc', 'netcat', 'telnet', 'port'), kp('Firewalls / security groups / NSGs', 'firewall*', 'security group*', 'nsg'), kp('Routing and listening address', 'route*', 'listening', 'ss', '0 0 0 0'), kp('TLS / authentication errors vs network', 'tls', 'authenticat*', 'credentials')],
    'I work up the layers. First DNS: does the hostname resolve to the expected IP, using dig or nslookup. Then port reachability with nc or curl to the database port: a timeout usually means a firewall, security group or NSG is dropping traffic, while connection refused means nothing is listening, so I check on the server with ss that the database listens on the right interface, not only localhost. I check routing, peering and route tables between networks. If the TCP connection works, the problem is higher up, such as TLS or authentication and credentials, which the app logs show.',
    'What does a timeout versus connection refused tell you?'),
  Q('devops-138', NET, 'MS', 'concept', 'Explain how TLS works and how you manage certificates in production.',
    [kp('Handshake: certificate, key exchange, session keys', 'handshake', 'key exchange', 'session key*'), kp('Certificate chain and CA trust', 'certificate chain', 'chain', 'ca', 'trust'), kp('TLS 1.3 and mTLS', 'tls 1 3', 'mtls', 'mutual'), kp('Automation: ACME/Let’s Encrypt, cert-manager', 'acme', 'lets encrypt', 'cert manager'), kp('Expiry monitoring and rotation', 'expir*', 'rotat*', 'monitor*')],
    'In the TLS handshake the server presents its certificate and the chain up to a trusted CA; the client validates the chain, hostname and expiry, then both sides perform a key exchange, typically ECDHE, to derive symmetric session keys for encryption. TLS 1.3 shortens the handshake to one round trip and removes weak ciphers. mTLS adds client certificates so both sides authenticate, common between services. In production I automate certificates with ACME, Let’s Encrypt and cert manager or cloud certificate managers, and monitor expiry with alerts, because expired certificates are a classic outage.',
    'How would you find all certificates expiring in the next 30 days?'),

  // ---------- AWS ----------
  Q('devops-139', AWS, 'EM', 'concept', 'Compare EC2, ECS, EKS and Lambda for running workloads on AWS.',
    [kp('EC2: virtual machines, full control', 'ec2', 'virtual machine*'), kp('ECS: AWS-native container orchestration, Fargate', 'ecs', 'fargate'), kp('EKS: managed Kubernetes', 'eks', 'kubernetes'), kp('Lambda: serverless functions, limits', 'lambda', 'serverless', '15 minutes'), kp('Trade-offs: control, ops, cost model', 'trade off*', 'control', 'cost')],
    'EC2 gives virtual machines with full control over the OS, suitable for legacy or specialised workloads, but you manage patching and scaling. ECS is AWS native container orchestration, simple and well integrated, and with Fargate you do not manage servers. EKS is managed Kubernetes, giving portability and the Kubernetes ecosystem at the cost of more complexity. Lambda runs serverless functions triggered by events, scales to zero and bills per request, but has limits such as a 15 minutes timeout and cold starts. I choose based on the trade off between control, operational effort and cost model.',
    'A batch job runs for two hours every night. Which option would you choose?'),
  Q('devops-140', AWS, 'MS', 'concept', 'How do S3 storage classes, lifecycle policies and security work?',
    [kp('Storage classes: Standard, IA, Glacier, Intelligent-Tiering', 'standard', 'infrequent access', 'glacier', 'intelligent tiering'), kp('Lifecycle rules transition and expire objects', 'lifecycle', 'transition', 'expire*'), kp('Block public access, bucket policies, encryption', 'block public access', 'bucket polic*', 'encrypt*'), kp('Versioning and object lock', 'versioning', 'object lock'), kp('Access via IAM roles / presigned URLs', 'presigned', 'iam')],
    'S3 storage classes trade access cost for storage cost: Standard for hot data, Standard Infrequent Access for data read rarely, Glacier tiers for archives, and Intelligent Tiering when access patterns are unknown. Lifecycle rules transition objects to cheaper classes after some days and expire old objects or versions. For security I keep Block Public Access on, use bucket policies and IAM roles with least privilege, enable default encryption with KMS, and use presigned URLs for temporary access. Versioning protects against accidental deletes, and object lock provides immutable backups against ransomware.',
    'How would you find out who deleted an object?'),
  Q('devops-141', AWS, 'SL', 'concept', 'How do you design a multi-account AWS organization?',
    [kp('AWS Organizations and OUs', 'organizations', 'ou*', 'organizational unit*'), kp('Account per environment/workload', 'account per', 'separate account*', 'workload*'), kp('SCPs as guardrails', 'scp*', 'service control polic*', 'guardrail*'), kp('Centralised logging/security accounts', 'log archive', 'security account', 'central*', 'cloudtrail'), kp('Control Tower / IAM Identity Center', 'control tower', 'identity center', 'sso')],
    'I use AWS Organizations with organizational units, OUs, for security, infrastructure, workloads split into prod and non-prod, and sandboxes. Each workload and environment gets a separate account, which limits blast radius and makes cost and permissions clear. Service control policies, SCPs, act as guardrails, for example deny disabling CloudTrail or using unapproved regions. A log archive account receives centralised CloudTrail and Config logs, and a security account runs GuardDuty and Security Hub. Control Tower automates the landing zone and account vending, and IAM Identity Center provides SSO with permission sets.',
    'How do workloads in different accounts talk to each other securely?'),

  // ---------- Service mesh ----------
  Q('devops-142', MESH, 'SL', 'concept', 'What is a service mesh, and when is it worth the complexity?',
    [kp('Sidecar or ambient proxies handle service traffic', 'sidecar*', 'proxy', 'envoy', 'ambient'), kp('mTLS between services', 'mtls', 'mutual tls'), kp('Traffic management: retries, timeouts, canary', 'retr*', 'timeout*', 'traffic split*', 'canary'), kp('Observability: golden metrics, tracing', 'observability', 'metrics', 'trac*'), kp('Cost: complexity, latency, resources', 'complexity', 'latency', 'overhead', 'resources')],
    'A service mesh such as Istio or Linkerd moves service to service networking concerns out of application code into proxies, traditionally an Envoy sidecar in every pod, or Istio ambient mode with per node proxies. It gives automatic mTLS between services with identity based authorization, traffic management such as retries, timeouts, circuit breaking and traffic splitting for canary releases, and uniform observability with golden metrics and tracing. It is worth it when you have many services and strong security or traffic control needs; for a handful of services the extra complexity, latency, resources and upgrade burden usually outweigh the benefits.',
    'What problems does Istio ambient mode try to solve?'),

  // ---------- Artifacts & code quality ----------
  Q('devops-143', ART, 'EM', 'concept', 'What is an artifact repository like Nexus or Artifactory, and why use one?',
    [kp('Stores build artifacts and packages (Maven, npm, Docker)', 'artifact*', 'maven', 'npm', 'docker', 'package*'), kp('Proxy and cache public registries', 'proxy', 'cache', 'public registr*'), kp('Versioning and immutable releases', 'version*', 'immutable', 'release*'), kp('Access control and retention', 'access control', 'retention', 'cleanup'), kp('Reliability against upstream outages / supply chain', 'outage*', 'rate limit*', 'supply chain')],
    'Nexus and Artifactory are artifact repository managers. They store our build outputs, such as Maven jars, npm packages, Helm charts and Docker images, with versioning so releases are immutable and traceable. They also proxy and cache public registries like Maven Central, npm and Docker Hub, which speeds builds, protects us from upstream outages and Docker Hub rate limits, and gives a control point for the supply chain, where packages can be scanned or blocked. They provide access control per repository and retention and cleanup policies to control storage.',
    'How would you clean up old snapshot artifacts safely?'),
  Q('devops-144', ART, 'EM', 'concept', 'How do you use SonarQube quality gates in a CI pipeline?',
    [kp('Static analysis: bugs, code smells, vulnerabilities', 'static analysis', 'bug*', 'code smell*', 'vulnerabilit*'), kp('Coverage and duplication metrics', 'coverage', 'duplicat*'), kp('Quality gate passes/fails the build', 'quality gate', 'fail*', 'build'), kp('Focus on new code', 'new code', 'clean as you code'), kp('PR decoration', 'pull request', 'decorat*', 'comment*')],
    'SonarQube performs static analysis to find bugs, code smells, security vulnerabilities and hotspots, and imports test coverage and duplication metrics. In CI the scanner runs after tests, and the pipeline waits for the quality gate result: if the gate fails, for example coverage on new code below 80 percent or any new critical vulnerability, the build fails. I set gates on new code, the clean as you code approach, so legacy debt does not block every change. Results are shown as pull request decoration with inline comments.',
    'Why might a team game coverage metrics, and how do you prevent it?'),

  // ---------- Troubleshooting / live ----------
  Q('devops-145', TS, 'SL', 'scenario', 'At 3 a.m., API latency spikes tenfold. Walk me through your investigation.',
    [kp('Check dashboards: which services, since when, errors', 'dashboard*', 'since when', 'scope'), kp('Correlate with deployments, config or traffic changes', 'deploy*', 'change*', 'traffic'), kp('Follow traces to the slow dependency', 'trac*', 'dependenc*', 'database'), kp('Check saturation: CPU, memory, connections, throttling', 'saturation', 'cpu', 'throttl*', 'connection*'), kp('Mitigate first, then root cause', 'mitigat*', 'rollback', 'scale', 'root cause')],
    'I open dashboards to scope it: which endpoints and services, since when, is it all regions or one, and are errors rising too. Then I correlate with changes: deployments, config or feature flag changes, traffic spikes or a dependency incident on a status page. Traces show which dependency is slow, often the database or an external API. I check saturation signals: CPU and CPU throttling, memory and GC, connection pools, queue depth and database locks. I mitigate first, by rolling back, scaling out, failing over or shedding load, and communicate in the incident channel, then do root cause analysis after recovery.',
    'Latency is high but CPU and memory look normal. What would you check next?'),
  Q('devops-146', TS, 'MS', 'scenario', 'A deployment is stuck: new pods stay in Pending or ImagePullBackOff. How do you fix it?',
    [kp('kubectl describe events', 'describe', 'event*'), kp('Pending: insufficient resources, taints, affinity, PVC', 'insufficient', 'taint*', 'affinity', 'pvc', 'pending'), kp('ImagePullBackOff: wrong tag, registry auth, network', 'imagepullbackoff', 'tag', 'imagepullsecret*', 'registry'), kp('Quotas / limit ranges', 'quota*', 'limitrange*'), kp('Rollout status / undo', 'rollout status', 'rollout undo', 'undo')],
    'I run kubectl describe pod and read the events. For Pending, the scheduler explains why: insufficient CPU or memory because requests are too large or the cluster is full, taints without tolerations, unsatisfiable affinity rules, an unbound PVC, or a namespace quota exceeded. For ImagePullBackOff, the image tag may not exist, the registry needs credentials through an imagePullSecret or workload identity, or nodes cannot reach the registry. kubectl rollout status shows progress; if needed I use rollout undo to restore the previous version while fixing it.',
    'How do you prevent a typo in an image tag from reaching production?'),

  // ---------- Platform engineering ----------
  Q('devops-147', PE, 'SL', 'concept', 'What is the difference between DevOps, SRE and platform engineering?',
    [kp('DevOps: culture and practices joining dev and ops', 'devops', 'culture', 'practice*'), kp('SRE: engineering approach to reliability, SLOs, error budgets', 'sre', 'site reliability', 'slo*', 'error budget*'), kp('Platform engineering: internal developer platform as a product', 'platform engineering', 'internal developer platform', 'product'), kp('Golden paths / self-service, Backstage', 'golden path*', 'self service', 'backstage'), kp('Complementary, not competing', 'complementary', 'together')],
    'DevOps is a culture and set of practices that join development and operations, with shared ownership, automation and fast feedback. SRE, site reliability engineering, is a concrete engineering approach to reliability from Google: SLOs, error budgets, toil reduction and blameless postmortems. Platform engineering builds an internal developer platform, treated as a product, that offers self service golden paths for creating, deploying and operating services, often with a portal like Backstage, so product teams get DevOps capabilities without each becoming infrastructure experts. They are complementary rather than competing.',
    'How would you measure whether an internal platform is successful?'),
  Q('devops-148', PE, 'SL', 'design', 'How would you build an internal developer portal with Backstage?',
    [kp('Software catalog with ownership', 'software catalog', 'catalog', 'owner*'), kp('Software templates (scaffolder) for golden paths', 'template*', 'scaffolder', 'golden path*'), kp('TechDocs / documentation', 'techdocs', 'documentation'), kp('Plugins integrate CI/CD, Kubernetes, monitoring', 'plugin*', 'integrat*'), kp('Adoption: start small, measure', 'adoption', 'start small', 'measure', 'feedback')],
    'Backstage gives three core features. The software catalog registers every service, API and resource with its owner team, dependencies and links, from catalog info files in each repo. Software templates, the scaffolder, implement golden paths: a developer fills a form and gets a new repo with CI CD, observability, security scanning and deployment config already wired. TechDocs renders documentation stored with the code. Plugins integrate CI/CD runs, Kubernetes status, monitoring, cost and on-call. For adoption I start small with the catalog and one high-value template, gather feedback, and measure time to first deployment.',
    'Why do many Backstage rollouts fail, and how would you avoid that?'),

  // ---------- Scripting ----------
  Q('devops-149', SC, 'EM', 'concept', 'How would you write a script to find the top 10 IP addresses in a web server access log?',
    [kp('Extract the IP field (awk/cut)', 'awk', 'cut', 'field', 'column'), kp('sort and uniq -c to count', 'sort', 'uniq'), kp('sort numerically descending and head', 'sort n', 'reverse', 'head'), kp('Python alternative with Counter', 'python', 'counter'), kp('Large file considerations', 'large', 'stream*', 'memory')],
    'In the shell I would extract the first field with awk print dollar one, or cut, then pipe to sort and uniq with the c flag to count occurrences, then sort numerically in reverse with sort n r, and take the first ten with head. That pipeline streams the file so memory stays low, except for the sort. For more complex parsing or logs in JSON, I would write a short Python script that streams the file line by line and uses collections Counter with most common of ten. For huge or compressed files I would use zcat and parallel processing.',
    'How would you extend it to count only 5xx responses in the last hour?'),
  Q('devops-150', SC, 'MS', 'concept', 'When do you choose Bash versus Python versus Go for automation?',
    [kp('Bash: glue for short command orchestration', 'bash', 'glue', 'short'), kp('Python: complex logic, APIs, libraries, testing', 'python', 'api*', 'librar*', 'boto3'), kp('Go: single static binaries, CLIs, operators, performance', 'go', 'binary', 'cli*', 'operator*'), kp('Maintainability, error handling and tests', 'maintain*', 'error handling', 'test*')],
    'Bash is ideal as glue for short scripts that orchestrate commands, like a CI step or simple file operations, but it gets fragile beyond a hundred lines because error handling and data structures are weak. Python is my choice for more complex logic, calling cloud APIs with libraries such as boto3 or the Azure SDK, parsing JSON and writing tests. Go suits tools that need to ship as a single static binary, CLIs, Kubernetes operators and controllers, or performance sensitive agents. The deciding factors are maintainability, error handling, tests and who will maintain it.',
    'What makes an automation script safe to run twice?'),
];
